using System;using System.Linq;using System.Collections.Generic;using System.Windows.Media.Media3D;
namespace GearLab {
 public static partial class RobotCad {
  static void ApplyGenerated(RobotBuild build,RobotJoint joint){var generated=joint.GeneratedBody;if(generated.Result==null||generated.Result.Parts==null)throw new Exception("Повреждены данные процедурного корпуса.");var replaced=build.Entries.Values.Where(e=>e.JointId==joint.Id&&(e.Category=="Корпус"||e.Category=="Крепёж"||e.Id.EndsWith("_output_shaft")||joint.BodyGenerator.Connected&&e.Category=="Проводка")).Select(e=>e.Id).ToArray();foreach(string id in replaced){build.Model.Parts.Remove(build.Entries[id].Part);build.Entries.Remove(id);}var axis=RobotMath.Frame(joint.Axis);foreach(var data in generated.Result.Parts){string id=joint.Id+"_proc_"+data.Id;var part=ProceduralBodySpec.Part(id,data);var edit=build.Document.BodyEdits.FirstOrDefault(e=>e.PartId==id);var local=axis;if(edit!=null&&edit.NativeStep!=null){part.NativeStep=edit.NativeStep;part.NativeVolume=edit.NativeVolume;part.NativeCentre=new Point3D(edit.NativeCentre[0],edit.NativeCentre[1],edit.NativeCentre[2]);part.MeshOverride=CADMeshCodec.Decode(edit.NativePreview);if(edit.NativeShift!=null)local=RobotMath.Translation(edit.NativeShift[0],edit.NativeShift[1],edit.NativeShift[2])*axis;}var b=data.Bounds;var shape=new MechanismPart{Id=id,Kind="block",Name=data.Label,SizeX=Math.Max(1,b[3]-b[0]),SizeY=Math.Max(1,b[4]-b[1]),Length=Math.Max(1,b[5]-b[2]),Density=data.Density};var entry=new RobotCadEntry{Id=id,JointId=joint.Id,OwnerId=data.InputSide?joint.ParentId:joint.Id,Part=part,Shape=shape,Local=local,InputSide=data.InputSide,Printable=data.Role!="hardware"&&data.Role!="insert"&&data.Role!="metal",Category=data.Role=="hardware"||data.Role=="insert"?"Крепёж":"Корпус",Density=data.Density};part.Reference=!entry.Printable;build.Entries[id]=entry;build.Model.Parts.Add(part);}if(ProceduralBodySpec.Fingerprint(build.Document,joint,joint.BodyGenerator)!=generated.Fingerprint)if(joint.BodyGenerator.Connected)build.Notes.Add(joint.Name+": гибкая проводка и разъёмы не проложены; условные наружные стержни не выдаются за готовые кабели.");build.Notes.Add(joint.Name+": процедурный корпус устарел; требуется локальное перестроение.");foreach(var issue in generated.Result.Issues.Where(i=>i.Status=="error"))build.Notes.Add(joint.Name+": "+issue.Message);if(joint.BodyGenerator.Connected)build.Notes.Add(joint.Name+": гибкая проводка и разъёмы не проложены; условные наружные стержни не выдаются за готовые кабели.");build.Notes.Add(joint.Name+": процедурный корпус "+joint.BodyGenerator.Variant+"; геометрия "+(generated.Result.GeometryValid?"проверена":"содержит ошибки")+". Допуск к изготовлению не подтверждён.");}
 }
}
